    [2] = {s = {["|1"] = "Make sure you do not leave without picking up a few Pickaxe.", ["|2"] = "Speak to Dkhaaya for a cutscene and to obtain Dkhaaya's research journal.", ["|3"] = "Enter Aydeewa Subterrane through the cave at (I-7) in Bhaflau Thickets.", ["|4"] = "Head to the room at (H-9) and begin mine in this room until you find one of three key items; Electrocell, Electropot, or Electrolocomotive.", ["|5"] = "Return to Dkhaaya who will reward you with a Lightning Band.", ["|6"] = "At this point the quest is completed, however, if you trade the Lightning Band to the Leypoint at Wajaom Woodlands (G-8) it will transform"}},
    [3] = {s = {["|1"] = "Speak to Tehf Kimasnahya in Aht Urhgan Whitegate at (F-8).", ["|2"] = "Speak to Ekhu Pesshyadha in Aht Urhgan Whitegate at (H-6).", ["|3"] = "Speak to Zabahf in Aht Urhgan Whitegate at (F-8).", ["|4"] = "Speak to Ekhu Pesshyadha to receive the Vial of luminous water.", ["|5"] = "Speak to Tehf Kimasnahya.", ["|6"] = "Go to the lower level of Aht Urhgan Whitegate (J-10) to trigger a cutscene.", ["|7"] = "Speak to Tehf Kimasnahya.", ["|8"] = "Zone and then speak to Tehf Kimasnahya again to receive your reward."}},
    [5] = {s = {["|1"] = "Speak to Waoud - (J-10) top floor.", ["|10"] = "Trade him the item and he will tell you to go to Aydeewa Subterrane.", ["|11"] = "Enter Aydeewa Subterrane at (G-7) in Bhaflau Thickets, and proceed to the platform at (H-9) for a cutscene.", ["|12"] = "When the cutscene is over, you will be returned to Aht Urhgan Whitegate and be able to change to Blue Mage.", ["|2"] = "He will offer to give you a divination and will ask the following questions.", ["|3"] = "Upon success, Waoud will mention seeing all five serpent symbols.", ["|4"] = "Below is a listing of the questions and answers.", ["|5"] = "Right after answering all his questions, Waoud will tell you which kind of treasure he's interested in, but you won't be able to progress", ["|6"] = "When Waoud asks for the treasure, he will use the following clues (Make sure you read the item entries themselves for important info!):", ["|7"] = "\"The treasure I would have you seek is a pinch of golden sand.", ["|8"] = "\"The treasure I would have you seek is a jewel.", ["|9"] = "\"The treasure I would have you seek is a precious stone."}},
    [6] = {s = {["|1"] = "Speak to Ratihb at Aht Urhgan Whitegate (J-12 Shararat Teahouse) for a cutscene that begins the quest.", ["|2"] = "Speak to Mafwahb at Aht Urhgan Whitegate (L-9 Palace Door) for a cutscene.", ["|3"] = "Go to Arrapago Reef Map 1.", ["|4"] = "Ensure you have a Lamian Fang Key.", ["|5"] = "Use the Lamian Fang Key on the Iron Gate at Arrapago Reef map 1 (J-10), then go immediately west on the small map to another Iron Gate.", ["|6"] = "Click on the ???", ["|7"] = "Enter Talacca Cove from Caedarva Mire (E-9) Map 1.", ["|8"] = "Go around the left side of the lake in the large room until you find a ??? spot and examine it for a cutscene and the key item Forgotten", ["|9"] = "Travel west into the tunnel entrance, then North to find the Rock Slab (follow the tunnel, you can't go wrong), examine the slab for a"}},
    [7] = {s = {["|1"] = "Talk to Shamarhaan (F-9) in Bastok Markets - short run from HP#2.", ["|2"] = "Head to Aht Urhgan Whitegate, and talk to Iruki-Waraki (K-9, top floor).", ["|3"] = "Speak with Ghatsad in Aht Urhgan Whitegate (I-7), inside of the Automaton Workshop.", ["|4"] = "Take the northern Port Ephramad ferry to Nashmau and go through North Gate to Caedarva Mire.", ["|5"] = "Find the ??? at (H-10) on the first boat, hidden beneath the stairs, to receive Antique automaton.", ["|6"] = "Speak to Ghatsad.", ["|7"] = "Wait until the next Vana'diel day and speak to Ghatsad to receive your new Automaton.", ["|8"] = "Speak with Iruki-Waraki (K-9, top floor) in Aht Urhgan Whitegate to complete the quest and receive your Animator."}},
    [12] = {s = {["|1"] = "After completing Vanishing Act re-zone and wait one Earth minute.", ["|2"] = "Talk to Qutiba at (K-12) for a cutscene.", ["|3"] = "You may have to talk to her several times and agree to listen to a recipe before the cutscene plays.", ["|4"] = "Trade Qutiba three pots of White Honey for another cutscene and your reward."}},
    [13] = {s = {["|1"] = "Speak to Dabhuh at (K-11) near The Pit in Aht Urhgan Whitegate to begin this quest.", ["|2"] = "Trade him a Merrow Scale to complete this quest."}},
    [14] = {s = {["|1"] = "If Suldiran is taken prisoner during Besieged, this quest will be unavailable until he is rescued.", ["|2"] = "Speak to Suldiran to begin this quest.", ["|3"] = "Trade Suldiran 2 Imp Wings to complete this quest."}},
    [15] = {s = {["|1"] = "Trade Ququroon all of the fish he desires.", ["|2"] = "There is a small chance that Ququroon will fail to make the stew.", ["|3"] = "This quest is repeatable once every real life minute.", ["|4"] = "This quest must be completed during the Rat Race quest, though it is not a prerequisite for that quest.", ["|5"] = "If you complete this quest prior to being to the part of Rat Race where you need a Nashmau Stew, you will need to do this quest yet again."}},
    [16] = {s = {["|1"] = "Speak to Ratihb (J-12) in Aht Urhgan Whitegate to start this quest.", ["|10"] = "Defeat Bukki and check the ??? again to get the Bag of gold pieces and complete this part of the quest.", ["|11"] = "Return to Aht Urhgan Whitegate and speak to Ratihb to complete this quest and receive your reward.", ["|2"] = "Speak to Ekhu Pesshyadha (H-6).", ["|3"] = "Speak to Jijiroon (H-8) in Nashmau.", ["|4"] = "Go up the stairs at (H-8) and zone into Caedarva Mire.", ["|5"] = "Obtain a Lamian Fang Key from the ??? at (I-7) if possible, otherwise obtain it from Merrows inside Arrapago Reef.", ["|6"] = "Travel to Arrapago Reef by way of the (I-6) entrance from Caedarva Mire.", ["|7"] = "Go to (F-10) on Map 1 to change onto Map 2, follow the right wall straight north (@ K-10 Map 2) once on this map to find a ???.", ["|8"] = "Click the ??? to see a cutscene.", ["|9"] = "Click it again to spawns an Imp NM named Bukki."}},
    [17] = {s = {["|1"] = "Speak to Milazahn for a cutscene.", ["|2"] = "Speak to Cacaroon (G-11) for a cutscene.", ["|3"] = "Trade Cacaroon 1,000 gil for another cutscene.", ["|4"] = "Zone into Mamook from the Mamool Ja Staging Point exit.", ["|5"] = "Head northwest to (E-8) and check the Viscous Liquid for a cutscene.", ["|6"] = "Examine the Viscous Liquid again to spawn Mamool Ja (NM).", ["|7"] = "Examine the Viscous Liquid after the NM is defeated for a cutscene.", ["|8"] = "Return to Milazahn for your reward."}},
    [19] = {s = {["|1"] = "Speak to Tsetseroon to begin this quest.", ["|2"] = "Head to Wajaom Woodlands (D-9) and zone into Aydeewa Subterrane.", ["|3"] = "Return to Tsetseroon to offically begin this quest.", ["|4"] = "Trade Tsetseroon a Tin Ore and a Cobalt Jellyfish.", ["|5"] = "Return to Aydeewa Subterrane (G-10 Map 3) and check the ??? at the top of the damaged stairwell for a cutscene.", ["|6"] = "Return to Tsetseroon for an Imperial Bronze Piece and to complete the quest.", ["|7"] = "If you chose not to look into Wawaroon's bag, you will receive the Map of Aydeewa Subterrane when you return to Tsetseroon instead; you"}},
    [20] = {s = {["|1"] = "Examine the unnamed target on a manhole cover at (L-7) Mount Zhayolm for a cutscene that begins this quest.", ["|2"] = "Trade a Pickaxe to the same unnamed target for another cutscene.", ["|3"] = "Head South to zone out of Mount Zhayolm, then zone back in.", ["|4"] = "Trade a Mythril Pick to the same unnamed target for the final cutscene and your reward."}},
    [21] = {s = {["|1"] = "Begin this quest by speaking to Waoud (J-10) once your Blue Mage is level 40 and you have completed Aht Urhgan Mission 2.", ["|2"] = "Tell Waoud that you want him to \"Gaze Away\" at your fate.", ["|3"] = "In the cut scene select \"i have\".", ["|4"] = "The quest will now show in your quest log.", ["|5"] = "Once you have the quest started, you need to head to the five main Staging Points with Blue Mage as your main job.", ["|6"] = "You will obtain a Permanent Key Item after each cutscene:", ["|7"] = "After you have all five Brand Key Items, speak to Waoud again to finish the quest."}},
    [22] = {s = {["|1"] = "(Wait one in game day since completing the last quest and re-zone into Aht Urhgan Whitegate if you haven't already.)", ["|2"] = "Speak to Waoud to begin the quest.", ["|3"] = "Raubahn will direct you to find and kill a Flan in the Navukgo Execution Chamber.", ["|4"] = "When in the Navukgo Execution Chamber, examine the Decorative Bronze Gate to start a BC fight.", ["|5"] = "Return to Aht Urhgan Whitegate and speak to Waoud.", ["|6"] = "You will be given a Sealed Immortal envelope", ["|7"] = "Deliver the envelope to Lathuya @ Aht Urhgan Whitegate F-8, on the second floor inside the stall.", ["|8"] = "Zone into Wajaom Woodlands from Aht Urhgan Whitegate (G/H-10 Stairwell), then head toward the south and zone into the Aydeewa Subterrane", ["|9"] = "Return to Aht Urhgan Whitegate and speak to Lathuya."}},
    [23] = {s = {["|1"] = "Speak with Waoud at (J-10) as a level 50+ Blue Mage.", ["|2"] = "Ask for a divination by selecting the \"Gaze away.\" dialogue option.", ["|3"] = "Go to the Imperial Whitegate door at (L-8) in Aht Urhgan Whitegate, and check it for a cut scene.", ["|4"] = "The quest is now listed in your current quest log.", ["|5"] = "Your next goal is to obtain two cutscenes in the Alzadaal Undersea Ruins.", ["|6"] = "After the above two cutscenes, it is time to progress to a battle.", ["|7"] = "Use the teleporter at (I-9) (the one to the right when entering the room), then examine the blank spot in the North-West corner of (G-7)", ["|8"] = "Defeat the Soulflayer, then examine the blank spot again for another cutscene and your reward."}},
    [24] = {s = {["|1"] = "Talk to Ratihb at Aht Urhgan Whitegate (J-12) at the Shararat Teahouse.", ["|2"] = "Examine the ??? in Arrapago Reef (H-10) as Corsair, level 40 or higher, for a cutscene.", ["|3"] = "Head to Maze of Shakhrami Map 2 (K-9).", ["|4"] = "Defeat the Lost Soul and check the Iron Door again for a cutscene with Imutira and to obtain a Wheel lock trigger.", ["|5"] = "Return to the ??? in the Arrapago Reef for another cutscene.", ["|6"] = "Speak to Ratihb, Aht Urhgan Whitegate (J-12) for your reward (you may have to speak to him twice)."}},
    [25] = {s = {["|1"] = "Examine the ??? in Arrapago Reef at (H-10) Map 1 for a cutscene.", ["|2"] = "You no longer have to be on Corsair for the rest of this quest.", ["|3"] = "You are asked to fish up a Hydrogauge.", ["|4"] = "Once you've fished up a Hydrogauge, trade it to Leleroon, Nashmau (G-7).", ["|5"] = "Head to (G-8) in Wajaom Woodlands and trade the Hydrogauge to the Leypoint.", ["|6"] = "Wait one minute, then examine the Leypoint again.", ["|7"] = "Return to the ??? in Arrapago Reef at (H-10) Map 1 for your reward."}},
    [26] = {s = {["|1"] = "While on Corsair, head to the Shararat Teahouse in Aht Urhgan Whitegate at (K-12) for a cutscene and the key item, Life float.", ["|2"] = "Head to the The Ashu Talif in Arrapago Reef through the Dvucca Isle Staging Point or Alzadaal Undersea Ruins.", ["|3"] = "Approach the Cutter for a cutscene.", ["|4"] = "Examine the Cutter to enter a battlefield against Yazquhl and Gowam.", ["|5"] = "You will receive your reward immediately following the cutscene after the fight.", ["|6"] = "Leleroon's letter (green) (Hands)", ["|7"] = "Leleroon's letter (blue) (Feet)", ["|8"] = "Leleroon's letter (red) (Body)"}},
    [27] = {s = {["|1"] = "Speak with Iruki-Waraki at (K-9) in Aht Urhgan Whitegate.", ["|2"] = "You can tell the Automaton belongs to Iruki-Waraki because it has a very unique personality.", ["|3"] = "Once in Nashmau proceed to (H-6) (second floor) and speak with Dnegan.", ["|4"] = "Exit Nashmau by the East gate into Caedarva Mire.", ["|5"] = "Go back to Iruki-Waraki in Aht Urhgan Whitegate to receive your Turbo Animator."}},
    [28] = {s = {["|1"] = "Must zone after previous quest in order to start this quest.", ["|10"] = "The next part of this quest is long winded and leaves you stuck in a remote area, so bring either a Warp Ring or an Scroll of Instant Warp.", ["|11"] = "The final ??? for this quest is located in Caedarva Mire, at (K-5), which is actually part of the Azouph Isle map.", ["|12"] = "The quickest way to reef is the Survival Guide to reef.", ["|13"] = "If you used the survival guide to reef, zone out then grab yourself a Lamian Fang Key and zone into the reef from (I-6).", ["|14"] = "For the reef you are going to need Silent Oils and Prism Powders, sub Dancer, or etc.", ["|15"] = "You'll find yourself at (I-11) on the map when you first zone into reef.", ["|16"] = "Apply Sneak (Status) and Invisible (Status), and run around to the Iron Gate at (J-10).", ["|17"] = "Once in Caedarva Mire Apply Invisible (Status) then head to K-6 and click the ??? behind the tree.", ["|18"] = "Enjoy the final cut-scene.", ["|2"] = "Speak with Iruki-Waraki in Aht Urhgan Whitegate for a cut-scene.", ["|3"] = "He gives you a shopping list of items needed to help his plan come to fruition.", ["|4"] = "You can be on any job from here on.", ["|5"] = "Return to Iruki-Waraki and trade him the items for a cut-scene.", ["|6"] = "Head to Nashmau, and seek out Dnegan for a cut-scene(@H-6 on the second floor).", ["|7"] = "Warning: Do NOT select the option \"Ask about the Automaton\" in this cut-scene.", ["|8"] = "The next part of the cutscene takes you to Nashmau Port, and you'll see Iruki's plan in action.", ["|9"] = "You are then presented with 3 options."}},
    [29] = {s = {["|1"] = "Speak with Iruki-Waraki who, during a cut-scene, asks you to inquire with his mentor, Shamarhaan about the situation.", ["|10"] = "Upon defeating Valkeng, a cut-scene will occur.", ["|11"] = "Return to Bastok Markets and speak to Shamarhaan for a cut-scene.", ["|12"] = "Travel back to Aht Urhgan Whitegate to speak with Iruki-Waraki once again for a cut-scene.", ["|13"] = "Travel to Nashmau and speak with Sajhra at (H-9) in the docks for another cut-scene.", ["|14"] = "Return to Iruki-Waraki in Aht Urhgan Whitegate and speak with him for one last cut-scene and to receive your reward: Puppetry Taj", ["|2"] = "You can be any job from here on.", ["|3"] = "Travel to Bastok Markets and talk to Shamarhaan at (F-9) who gives a cut-scene and the key item Valkeng's memory chip from his own", ["|4"] = "Travel to Mount Zhayolm and reach the position (L-8) to investigate the ??? located on a round steam vent on the ground to receive the key", ["|5"] = "After obtaining Valkeng's memory chip and the Toggle switch, find your way to Talacca Cove for a battle.", ["|6"] = "Examine the Rock Slab in the North-Western direction of the area for a cut-scene and to enter the battlefield to fight Shamarhaan's old", ["|7"] = "If underleveled/geared, this battle can prove to be very challenging for an unbalanced and low-number group.", ["|8"] = "Valkeng is an Automaton type mob beginning as a Harlequin Frame and every 30 seconds, will change into a different frame depending on the", ["|9"] = "Each frame Valkeng changes to has significant stat and strategy changes."}},
    [30] = {s = {["|1"] = "Speak with Mishhar near HP#1 in Whitegate.", ["|10"] = "Return to Mishhar for your reward", ["|2"] = "Go to the Teahouse (J-12) for another cutscene.", ["|3"] = "Return to Mishhar (H-8)", ["|4"] = "Enter Mamook from (D-12) in Wajaom Woodlands and click on a nearby ???", ["|5"] = "Head to Jade Sepulcher and click the BCNM entrance (\"Ornamental Door\") for a cutscene", ["|6"] = "Click again to enter the BCNM: \"Moment of Truth\"", ["|7"] = "Blacktattoo Vedool Ja (BLM)", ["|8"] = "Shadowhand Kajeel Ja (NIN)", ["|9"] = "Whitetattoo Rahool Ja (WHM)"}},
    [40] = {s = {["|1"] = "Speak to Waoud (J-10) Aht Urhgan Whitegate to flag the quest.", ["|2"] = "Obtain a Blue Mage's Testimony from Mamool Ja Mimickers.", ["|3"] = "Trade the testimony to the Imperial Whitegate and you will be teleported to Jade Sepulcher.", ["|4"] = "Trade the testimony to the Ornamental Door to initiate a battle.", ["|5"] = "Defeat Raubahn to complete the quest and raise your level cap to 80."}},
    [41] = {s = {["|1"] = "Obtain a Corsair's Testimony from Merrow Icedancers, Merrow Kabukidancers, Merrow Chantress, or Lamia Fatedealer.", ["|2"] = "You end up in the correct area to continue after the conclusion of Against All Odds", ["|3"] = "Head to (H-10) Arrapago Reef (Map 1) and check the ??? for a cutscene.", ["|4"] = "Upon trading the testimony to the ???, you will receive another short cutscene and then be teleported to Talacca Cove.", ["|5"] = "Trade the Corsair's Testimony to the Rock Slab to enter a BCNM.", ["|6"] = "The fight will end when the boss reaches 20%HP or less."}},
    [43] = {s = {["|1"] = "Speak to Fari-Wari at the Shararat Teahouse in Aht Urhgan Whitegate (K-12) for a cutscene that begins the quest.", ["|2"] = "Go to Wajaom Woodlands (C-8) to enter Halvung.", ["|3"] = "Speak to Fari-Wari.", ["|4"] = "Wait a game day and speak to Fari-Wari to complete the quest."}},
    [44] = {s = {["|1"] = "Speak to Fari-Wari in Aht Urhgan Whitegate (K-12) for a cutscene that begins the quest.", ["|2"] = "With the key item Biyaada's letter, go to Al Zahbi and speak to Gaweesh (G-8) and Talhaal (H-6).", ["|3"] = "Complete the quests When the Bow Breaks and Fist of the People.", ["|4"] = "Speak to Fari-Wari to complete the quest."}},
    [45] = {s = {["|1"] = "While the quest Ode to the Serpents is active, speak to Gaweesh in Al Zahbi (G-8).", ["|2"] = "In Wajaom Woodlands kill Aht Urhgan Attercops (Spiders) until you get a Frayed Arrow.", ["|3"] = "Go to Giwahb Watchtower in Wajaom Woodlands (F-5) and trade the Frayed Arrow to the door for a cutscene that completes the quest."}},
    [46] = {s = {["|1"] = "While the quest Ode to the Serpents is active, speak to Talhaal in Al Zahbi (H-6).", ["|2"] = "Speak to Fari-Wari in Aht Urhgan Whitegate (K-12).", ["|3"] = "In Wajaom Woodlands kill Wajaom Tigers until you get a Rusty Medal.", ["|4"] = "Go to the Leypoint in Wajaom Woodlands (G-8) and trade the Rusty Medal for a cutscene that completes the quest."}},
    [47] = {s = {["|1"] = "Speak to Fari-Wari in Aht Urhgan Whitegate (K-12) for a cutscene that begins the quest.", ["|2"] = "Go to (G-9) and talk to Eunheem.", ["|3"] = "Talk to Nadeey at (K-7) inside the Walahra Temple.", ["|4"] = "Talk to Mihli Aliapoh in Al Zahbi (H-7), who tells you to obtain a Colorful Hair.", ["|5"] = "Use the (I-7) Bhaflau Thickets entrance to Aydeewa Subterrane (not the Survival Guide entrance), and find the ??? at (H-8) after sliding", ["|6"] = "Return to Fari-Wari to complete the quest."}},
    [48] = {s = {["|1"] = "Talk to Fari-Wari at the Shararat Teahouse (K-12) for a cutscene that begins the quest.", ["|2"] = "Head to Mount Zhayolm and click on Sprightly Footsteps (L-7) between 18:00-06:00.", ["|3"] = "Click on on Withered Petals (L-6, southeast portion near the coastal cliffs) between 18:00-06:00.", ["|4"] = "Trade a Hydrangea to Fari-Wari.", ["|5"] = "Trade the Hydrangea to the Withered Petals in Mount Zhayolm.", ["|6"] = "Return to Fari-Wari for a cutscene and an Imperial Gold Piece.", ["|7"] = "Speak to Fari-Wari after this to learn Trust Gadalar.", ["|8"] = "Speak to Fari-Wari after the day changes to receive a Mercenary Camp Entry Slip."}},
    [62] = {s = {["|1"] = "Note: You must zone after completing Delivering the Goods before he will give you this quest.", ["|2"] = "Speak to Ulamaal to begin this quest.", ["|3"] = "Speak to Fochacha at (I-9).", ["|4"] = "Head to the Alchemy Guild at (G-5) for a cutscene.", ["|5"] = "Begin harvesting Wajaom Woodlands to obtain the Rainbow berry.", ["|6"] = "Speak to Ulamaal for your reward."}},
    [63] = {s = {["|1"] = "Speak to Wazyih at (F-11) to begin the quest.", ["|10"] = "(J-7) Behind Kahah Hobichai", ["|11"] = "(I-5) Flameserpent Square", ["|12"] = "(H-9) Tunnel to Chocobo alley from Galeserpent Square", ["|13"] = "(J-9) Galeserpent Square", ["|14"] = "Zone back in to Aht Urhgan Whitegate from Al Zahbi for a cutscene.", ["|15"] = "Return to Wazyih at (F-11) in Aht Urhgan Whitegate.", ["|16"] = "Finally, speak to Saliyahf at (G-7) for your reward and to finish the quest.", ["|2"] = "Talk to Saliyahf at (G-7).", ["|3"] = "Return to Wazyih.", ["|4"] = "Walk towards the crates at (F-9).", ["|5"] = "Return to Saliyahf.", ["|6"] = "Speak to Wazyih again.", ["|7"] = "(G-7) in the water", ["|8"] = "(G-8) entrance to the south tunnel", ["|9"] = "(I-10) Chocobo alley"}},
    [65] = {s = {["|1"] = "Speak to Mhasbaf in Aht Urhgan Whitegate at (J-8) to begin this quest.", ["|2"] = "Walk downstairs to the pillar at (J-8) for a cutscene.", ["|3"] = "Speak to Tohka Telposkha at (I-8) for a cutscene.", ["|4"] = "Talk to Rubahah at (F-9) and repeat this process, and then Cacaroon at (G-11) and do the same thing.", ["|5"] = "Walk to (I-11) (Down the ramp beside the ferry) for a cutscene to obtain the Letter from Bernahn.", ["|6"] = "Speak to Tataroon at (G-8) in Nashmau to complete the quest and obtain your reward."}},
    [66] = {s = {["|1"] = "Speak to Kakkaroon.", ["|2"] = "Speak to Nadee Periyaha Aht Urhgan Whitegate (H-9).", ["|3"] = "Speak to Cacaroon Aht Urhgan Whitegate (G-11).", ["|4"] = "Trade Cacaroon one Imperial Bronze Piece.", ["|5"] = "Now you must complete Cook-a-roon? for a Nashmau Stew", ["|6"] = "Trade a Nashmau Stew to Kyokyoroon back in Nashmau (H-7).", ["|7"] = "Speak to Kakkaroon to complete the quest."}},
    [74] = {s = {["|1"] = "Approach Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene that begins the quest.", ["|10"] = "Examine the Runic Seal in Alzadaal Undersea Ruins (I-8/9) to start the BCNM fight.", ["|11"] = "Upon defeating the BCNM you will receive the Whisper of radiance.", ["|12"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) for a cutscene.", ["|13"] = "Speak to Naja Salaheem to choose your reward.", ["|2"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) to receive the Imperial missive.", ["|3"] = "Examine the Audience Chamber in Ru'Lude Gardens at (H-6).", ["|4"] = "You must speak to representatives from the main nations, these can be done in any order.", ["|5"] = "Return to the Audience Chamber in Ru'Lude Gardens at (H-6) for the Jeunoan approval letter.", ["|6"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) to receive the present for Megomak.", ["|7"] = "Examine the Acid-eaten Door in Mount Zhayolm at the northwest corner of (I-9) to receive the Megomak's shopping list.", ["|8"] = "Trade 3 Slabs of Plumbago to the Acid-eaten Door to receive the lightning cell.", ["|9"] = "Examine the blank target on the single dark lamp at the Nyzul Isle Staging Point in Alzadaal Undersea Ruins (J-8/9) for a cutscene."}},
    [75] = {s = {["|1"] = "Approach Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene that begins the quest.", ["|2"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9).", ["|3"] = "Examine the Acid-eaten Door in Mount Zhayolm at (I-9) to receive a short cutscene.", ["|4"] = "Trade 3 Slabs of Plumbago to the Acid-eaten Door to receive the lightning cell.", ["|5"] = "Examine the Blank Target in Nyzul Isle Staging Point at (J-8/9) for a cutscene.", ["|6"] = "Examine the Runic Seal in Alzadaal Undersea Ruins (I-8/9) to start the BCNM fight.", ["|7"] = "Speak to Naja Salaheem to choose your reward."}},
    [76] = {s = {["|1"] = "Enter the Walahra Temple in Aht Urhgan Whitegate at (J/K-8) for a cutscene.", ["|12"] = "Should your appraisal succeed, you will have to zone and talk to Yoyoroon again to receive the Talisman of the rebel gods.", ["|13"] = "Enter the Walahra Temple in Aht Urhgan Whitegate at (J/K-8) for a cutscene to receive the Talisman key.", ["|14"] = "Enter Hazhalm Testing Grounds and examine the Entry Gate to view a cutscene.", ["|15"] = "Examine the Entry Gate again to enter a BCNM.", ["|2"] = "Speak to Yoyoroon in Nashmau in (G-6), upper level stalls.", ["|20"] = "After winning the battle, you will enter a cutscene where you will choose your reward.", ["|21"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) for a cutscene to complete the quest.", ["|4"] = "Obtain a Timeworn Talisman from Ephramadian Shades in Arrapago Reef or Caedarva Mire.", ["|8"] = "Trade the Timeworn Talisman and a Sutlac, Irmik Helvasi, or even both to Yoyoroon in Nashmau."}},
    [77] = {s = {["|1"] = "Speak to Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene that begins the quest.", ["|10"] = "After winning the battle, you will enter a cutscene where you will choose your reward.", ["|11"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) for a cutscene.", ["|12"] = "Speak to Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene which completes the quest, along with an Imperial Gold Piece.", ["|2"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9).", ["|3"] = "Speak to Yoyoroon in Nashmau in (G-6).", ["|4"] = "Obtain a Timeworn Talisman to be appraised, along with Sutlac and/or Irmik Helvasi to persuade Yoyoroon.", ["|5"] = "Trade the Timeworn Talisman and a Sutlac, Irmik Helvasi, or even both to Yoyoroon in Nashmau.", ["|6"] = "Once your appraisal succeeds, you must zone and talk to Yoyoroon again to receive the Talisman of the rebel gods.", ["|7"] = "Examine the Imperial Whitegate door in Aht Urhgan Whitegate at (L8/9) for a cutscene to receive the key items: Talisman key and Spatial", ["|8"] = "Enter Hazhalm Testing Grounds and examine the Entry Gate to view a cutscene.", ["|9"] = "Examine the Entry Gate again to enter a BCNM."}},
    [78] = {s = {["|1"] = "Speak to Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene that begins the quest.", ["|10"] = "Return to Imperial Whitegate for a cutscene to receive the key items: Talisman key and spatial pressure barometer.", ["|11"] = "Enter Hazhalm Testing Grounds and examine the Entry Gate to view a cutscene.", ["|12"] = "Examine the Entry Gate again to enter a BCNM.", ["|13"] = "After winning the battle, you will enter a cutscene where you will choose your reward.", ["|14"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) for a cutscene.", ["|15"] = "Speak to Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene to complete the quest.", ["|2"] = "Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9).", ["|3"] = "Speak to Yoyoroon in Nashmau in (G-6).", ["|4"] = "Obtain a Timeworn Talisman from Ephramadian Shades in Arrapago Reef or Caedarva Mire.", ["|8"] = "Trade the Timeworn Talisman and a Sutlac, Irmik Helvasi, or even both to Yoyoroon in Nashmau.", ["|9"] = "Should your appraisal succeed, you will have to zone and talk to Yoyoroon again to receive the Talisman of the rebel gods."}},
    [90] = {s = {["|1"] = "Players must be in possession of the previous rank's Wildcat badge, and have met the prerequisites for undertaking the appropriate", ["|2"] = "You can skip this quest by purchasing PFC Wildcat Badge from Curio Vendor Moogle once you meet the 25 Mercenary Rank points requirement,", ["|3"] = "Trade an Imp Wing to Naja Salaheem."}},
    [91] = {s = {["|1"] = "After accepting the quest, find the Warhorse Hoofprint located somewhere in the Aht Urhgan regions.", ["|2"] = "Click on the Warhorse Hoofprint to receive the Dark Rider hoofprint.", ["|3"] = "Return to Naja to complete the quest."}},
    [92] = {s = {["|1"] = "After accepting the quest, talk to Nafiwaa at the Alchemist's Guild in Aht Urhgan Whitegate (G-5).", ["|2"] = "After receiving the 5 test tube key items, visit various ponds in Bhaflau Thickets and Wajaom Woodlands:", ["|3"] = "Return to Nafiwaa for a cutscene and begin the mixing process.", ["|4"] = "The quality of the mixture determines your imperial currency reward.", ["|5"] = "Wait a game day and zone at least once, and then return to Abquhbah for a cutscene.", ["|6"] = "Choose Helping his fellow mercenaries to complete the quest."}},
    [93] = {s = {["|1"] = "Talk to Naja to receive the Quartz transmitter.", ["|2"] = "Find the Warhorse Hoofprint and click on it to place the Quartz Transmitter.", ["|3"] = "Return to Naja to complete the quest."}},
    [94] = {s = {["|1"] = "Talk to Naja.", ["|2"] = "Go to Balrahn Way for another cutscene.", ["|3"] = "Obtain a Sutlac and head off to Nashmau.", ["|4"] = "At (H-9) in Nashmau, another cutscene will take place.", ["|5"] = "Trade a Sutlac to Totoroon.", ["|6"] = "Exit East to Caedarva Mire and go to (I-10).", ["|7"] = "Return to Naja to complete the quest."}},
    [95] = {s = {["|1"] = "In this trial, you must count three NPCs doing push-ups and determine who did the least.", ["|2"] = "In this trial, you must give a \"message advancement prompt\" with proper timing as the three NPCs do sit-ups.", ["|3"] = "In this final trial, you must give prompts to the three NPCs so that they finish running at the same time."}},
    [96] = {s = {["|1"] = "Talk to Abquhbah to initiate the quest.", ["|10"] = "Return to both patches of mushrooms between 04:00 and 06:00 game-time to harvest young Scourshroom.", ["|11"] = "Return to Abquhbah to help clean the weapon.", ["|12"] = "After cleaning the weapon twice, you may choose to complete the quest or continue cleaning.", ["|2"] = "He will redirect you to Hagakoff at (K-10) in Aht Urhgan Whitegate", ["|3"] = "Talk to Abquhbah again.", ["|4"] = "Talk to Hagakoff again.", ["|5"] = "Talk to Abquhbah again.", ["|6"] = "Enter Aydeewa Subterrane from Wajaom Woodlands (I-10).", ["|7"] = "Head to the room at (I-9) in Aydeewa Subterrane.", ["|8"] = "Repeat the same process but at (E-7).", ["|9"] = "Zone and wait for the game day to change."}},
    [97] = {s = {["|1"] = "Enter Naja's office to start the quest.", ["|10"] = "Upgraded beastmen items (such as Lamian Kaman or Lamian Kaman +1) will not work.", ["|11"] = "Beastmen items from the west (Yagudo, Orc, Goblin, et cetera) will not work.", ["|12"] = "Trade 2 Imperial Mythril Pieces to Abquhbah to start the third trial.", ["|13"] = "Fulfill requests without fail.", ["|14"] = "Bigger than a Marid.", ["|15"] = "Mythralline Wellspring.", ["|16"] = "A detective agency.", ["|17"] = "Empyrean Incense.", ["|18"] = "Warjal.", ["|19"] = "Blackrust.", ["|2"] = "Trade 3 Imperial Gold Pieces to Abquhbah, he will give you the Officer Academy manual.", ["|20"] = "He tripped over his right foot.", ["|21"] = "After all 3 trials are complete, you will be awarded your promotion.", ["|3"] = "Trade 2 Imperial Mythril Pieces to Abquhbah to start the first trial.", ["|8"] = "Trade 2 Imperial Mythril Pieces to Abquhbah to start the second trial.", ["|9"] = "Examples include:"}},
    [98] = {s = {["|1"] = "The quest is started by entering the Salaheem's Sentinels office.", ["|10"] = "Talk to Abquhbah to start the second trial.", ["|11"] = "In this task, you will be asked several questions in a cipher.", ["|12"] = "Language:", ["|13"] = "You will be asked 4 questions.", ["|14"] = "If you fail, you may retry the following Earth minute for no additional fee.", ["|15"] = "After you succeed, wait a game day and zone.", ["|16"] = "Talk to Abquhbah to start the third trial.", ["|17"] = "This game is the same as Rock-Paper-Scissors.", ["|18"] = "The three critters are Beetle, Crab, and Ghost.", ["|19"] = "The first opponent you fight, after a lengthy cutscene, is Arcuhbah.", ["|2"] = "Trade Abquhbah 5 Imperial Gold Pieces.", ["|20"] = "The second opponent you fight is a team-up of Fubruhn and Ugrihd.", ["|21"] = "The third opponent you fight is the Drill Sergeant.", ["|22"] = "The final opponent you fight is Koja Salaheem.", ["|23"] = "After winning, wait until the game day changes and zone.", ["|24"] = "Talk to Abquhbah between 15:00 and 17:00 game-time to complete the quest.", ["|3"] = "Wait until the game day changes and zone.", ["|4"] = "Talk to Abquhbah to start the first trial.", ["|5"] = "In this task, you will be shown 12 humes.", ["|6"] = "There are 2 types of queries:", ["|7"] = "You must solve 3 rounds to succeed at this task.", ["|8"] = "If you fail, you may retry the following Earth minute for no additional fee.", ["|9"] = "After you succeed, wait for the game day to change and zone."}},
}
